// The tool list has one source, the skill folders and each character's When to call table. The copies
// (plugin.json, the root README, both bucket READMEs) are generated by scripts/lists.mjs, and --check
// names each one that has drifted (ADR 0004).
//
//   node --test test/characters/lists.test.mjs
import { after, describe, test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { cpSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const repo = resolve(".");
const script = join(repo, "scripts/lists.mjs");
const COPIES = [".claude-plugin/plugin.json", "README.md", "skills/tools/README.md", "skills/characters/README.md"];

const run = (root, mode) => spawnSync("node", [script, mode, "--root", root], { encoding: "utf8" });

// A temp copy of what the script reads: the four copies and every SKILL.md.
const dirs = [];
const copyRepo = () => {
  const dir = mkdtempSync(join(tmpdir(), "lists-"));
  dirs.push(dir);
  mkdirSync(join(dir, ".claude-plugin"));
  for (const f of COPIES) cpSync(join(repo, f), join(dir, f));
  for (const bucket of ["characters", "tools"]) {
    for (const name of readdirSync(join(repo, "skills", bucket)).filter((n) => statSync(join(repo, "skills", bucket, n)).isDirectory())) {
      mkdirSync(join(dir, "skills", bucket, name), { recursive: true });
      cpSync(join(repo, "skills", bucket, name, "SKILL.md"), join(dir, "skills", bucket, name, "SKILL.md"));
    }
  }
  return dir;
};
after(() => dirs.forEach((d) => rmSync(d, { recursive: true, force: true })));

const edit = (dir, file, fn) => writeFileSync(join(dir, file), fn(readFileSync(join(dir, file), "utf8")));
const snapshot = (dir) => Object.fromEntries(COPIES.map((f) => [f, readFileSync(join(dir, f), "utf8")]));

describe("scripts/lists.mjs", () => {
  test("--check passes on the repo as it is", () => {
    const r = run(repo, "--check");
    assert.equal(r.status, 0, r.stderr);
  });

  test("--write on the repo as it is changes nothing", () => {
    const dir = copyRepo();
    const before = snapshot(dir);
    assert.equal(run(dir, "--write").status, 0);
    assert.deepEqual(snapshot(dir), before);
  });

  const drifts = {
    "a root README line removed": [
      "README.md",
      (t) => t.replace(/^- `tdd`: called by associates\.\n/m, ""),
    ],
    "a plugin.json entry added": [
      ".claude-plugin/plugin.json",
      (t) => t.replace('"./skills/tools/tdd",', '"./skills/tools/tdd",\n    "./skills/tools/not-a-skill",'),
    ],
    "a plugin.json entry removed": [
      ".claude-plugin/plugin.json",
      (t) => t.replace('    "./skills/tools/tdd",\n', ""),
    ],
    "a Called by tail changed in the tools README": [
      "skills/tools/README.md",
      (t) => t.replace("Test-driven development: red, green, refactor. Called by associates.", "Test-driven development: red, green, refactor. Called by donna."),
    ],
    "a tool moved to the wrong group in the tools README": [
      "skills/tools/README.md",
      (t) => {
        const line = t.match(/^- \*\*\[tdd\][^\n]*\n/m)[0];
        return t.replace(line, "").replace("## User-invoked\n\n", `## User-invoked\n\n${line}`);
      },
    ],
    "the characters README gaining a stray entry": [
      "skills/characters/README.md",
      (t) => `${t}- **[nobody](./nobody/SKILL.md)**: not a skill.\n`,
    ],
  };
  for (const [what, [file, fn]] of Object.entries(drifts)) {
    test(`${what}: --check exits 1 and names ${file}, and --write restores it byte for byte`, () => {
      const dir = copyRepo();
      const before = snapshot(dir);
      edit(dir, file, fn);
      assert.notEqual(readFileSync(join(dir, file), "utf8"), before[file], "the edit changed nothing");
      const r = run(dir, "--check");
      assert.equal(r.status, 1);
      assert.match(r.stderr, new RegExp(file.replace(/[.\\/]/g, "\\$&")));
      assert.equal(run(dir, "--write").status, 0);
      assert.deepEqual(snapshot(dir), before);
      assert.equal(run(dir, "--check").status, 0);
    });
  }

  test("--check names every file that drifted, and only those", () => {
    const dir = copyRepo();
    edit(dir, "README.md", (t) => t.replace(/^- `tdd`: called by associates\.\n/m, ""));
    edit(dir, ".claude-plugin/plugin.json", (t) => t.replace('    "./skills/tools/tdd",\n', ""));
    const r = run(dir, "--check");
    assert.match(r.stderr, /README\.md/);
    assert.match(r.stderr, /plugin\.json/);
    assert.doesNotMatch(r.stderr, /skills\/tools\/README\.md|skills\/characters\/README\.md/);
  });

  test("the hand-written one-liners are kept by name when the list is regenerated", () => {
    const dir = copyRepo();
    edit(dir, "skills/tools/README.md", (t) => t.replace("Test-driven development: red, green, refactor.", "Red, green, refactor, in our own words."));
    assert.equal(run(dir, "--check").status, 0, "a new summary is not drift");
    edit(dir, "skills/tools/README.md", (t) => t.replace("Called by associates.", "Called by donna."));
    run(dir, "--write");
    assert.match(readFileSync(join(dir, "skills/tools/README.md"), "utf8"), /Red, green, refactor, in our own words\. Called by associates\./);
  });

  test("a character's When to call table says who calls a tool", () => {
    const dir = copyRepo();
    edit(dir, "skills/characters/louis/SKILL.md", (t) => t.replace("| `/suits:money-check` | the diff or spec", "| `/suits:tdd` | the diff has no test. |\n| `/suits:money-check` | the diff or spec"));
    assert.equal(run(dir, "--check").status, 1);
    run(dir, "--write");
    assert.match(readFileSync(join(dir, "skills/tools/README.md"), "utf8"), /Test-driven development: red, green, refactor\. Called by associates, louis\./);
    assert.match(readFileSync(join(dir, "README.md"), "utf8"), /^- `tdd`: called by associates, louis\.$/m);
  });

  test("a new user-invoked tool goes under User-invoked in the three copies", () => {
    const dir = copyRepo();
    mkdirSync(join(dir, "skills/tools/zeta"));
    writeFileSync(join(dir, "skills/tools/zeta/SKILL.md"), "---\nname: zeta\ndescription: Does a thing. Use when asked.\ndisable-model-invocation: true\n---\n\nBody.\n");
    const r = run(dir, "--check");
    assert.equal(r.status, 1);
    assert.match(r.stderr, /plugin\.json/);
    run(dir, "--write");
    assert.match(readFileSync(join(dir, ".claude-plugin/plugin.json"), "utf8"), /"\.\/skills\/tools\/zeta"\n/);
    const userBlock = (t) => t.split(/^#{2,3} Model-invoked/m)[0];
    assert.match(userBlock(readFileSync(join(dir, "README.md"), "utf8")), /^- `zeta`: /m);
    assert.match(userBlock(readFileSync(join(dir, "skills/tools/README.md"), "utf8")), /^- \*\*\[zeta\]\(\.\/zeta\/SKILL\.md\)\*\*: Does a thing\./m);
    assert.equal(run(dir, "--check").status, 0);
  });

  test("a bad mode or a missing mode exits 2 with a usage line", () => {
    const r = spawnSync("node", [script], { encoding: "utf8" });
    assert.equal(r.status, 2);
    assert.match(r.stderr, /usage/i);
  });
});

describe("package.json and CLAUDE.md", () => {
  test("npm run lists writes the copies", () => {
    assert.equal(JSON.parse(readFileSync("package.json", "utf8")).scripts.lists, "node scripts/lists.mjs --write");
  });
  test("CLAUDE.md says to run it first", () => {
    assert.match(readFileSync("CLAUDE.md", "utf8"), /run `npm run lists` first/i);
  });
  test("npm run check-skills runs the check", () => {
    assert.match(readFileSync("scripts/check-skills.mjs", "utf8"), /lists\.mjs/);
  });
  test("ADR 0004 records the decision", () => {
    const adr = readFileSync("docs/adr/0004-the-tool-list-has-one-source.md", "utf8");
    assert.match(adr, /^# /m);
    assert.match(adr, /^## Decision/m);
  });
});
